descriptor.templateCss:
.nk-root {
  position: relative;
  width: 100%;
  height: 100%;
  overflow: hidden;
  font-family: Roboto, "Helvetica Neue", Arial, sans-serif;
  color: #222;
}
.nk-stage {
  position: absolute;
  left: 0;
  top: 0;
  transform-origin: 0 0;
}
.nk-bg {
  position: absolute;
  left: 0;
  top: 0;
  width: 100%;
  height: 100%;
  pointer-events: none;
  user-select: none;
}

/* gépgombok */
.nk-gomb {
  position: absolute;
  transform: translate(-50%, -50%);
  box-sizing: border-box;
  padding: 0 12px;
  border: none;
  border-radius: 24%;
  background: linear-gradient(135deg, #a8d98a 0%, #6fb24f 100%);
  box-shadow: 0 4px 10px rgba(0, 0, 0, .18);
  color: #111;
  font-weight: 700;
  white-space: nowrap;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
}
.nk-gomb:hover { filter: brightness(1.07); }
.nk-gomb.nk-ures { font-size: 1.3em; }

/* Folyadék kártya (alapméret 340 px széles, a JS skálázza) */
.nk-folyadek {
  position: absolute;
  width: 340px;
  box-sizing: border-box;
  padding: 12px 16px 14px;
  transform-origin: 0 0;
  background: linear-gradient(135deg, rgba(255, 255, 255, .94) 0%, rgba(214, 236, 203, .9) 100%);
  border: 1px solid #b9dca6;
  border-radius: 22px;
  box-shadow: 0 6px 18px rgba(0, 0, 0, .12);
}
.nk-cim {
  text-align: center;
  font-size: 15px;
  font-weight: 700;
  margin-bottom: 8px;
  color: #222;
}
.nk-sor {
  display: flex;
  justify-content: space-between;
  align-items: center;
  height: 28px;
  font-size: 12.5px;
  color: #333;
}
.nk-sor b { font-size: 13.5px; color: #222; }
.nk-bevitel {
  display: flex;
  gap: 10px;
  margin-top: 8px;
}
.nk-bevitel input {
  flex: 1;
  min-width: 0;
  height: 34px;
  box-sizing: border-box;
  border: 1px solid #cfe3c4;
  border-radius: 17px;
  padding: 0 14px;
  font-size: 12px;
  background: #fff;
  outline: none;
}
.nk-bevitel input:focus { border-color: #7dbb5c; }
.nk-bevitel input.nk-hiba { border-color: #e74c3c; }
.nk-bevitel button {
  height: 34px;
  padding: 0 16px;
  border: none;
  border-radius: 17px;
  background: linear-gradient(135deg, #a8d98a 0%, #6fb24f 100%);
  box-shadow: 0 3px 8px rgba(0, 0, 0, .15);
  color: #111;
  font-size: 12px;
  font-weight: 700;
  cursor: pointer;
}
.nk-bevitel button:hover { filter: brightness(1.07); }
.nk-bevitel button:disabled { opacity: .6; cursor: default; }
.nk-msg {
  min-height: 14px;
  margin-top: 6px;
  font-size: 11px;
  font-weight: 600;
  text-align: center;
  line-height: 14px;
}

descriptor.controllerScript:
// =====================================================================
//  NGN KONTÉNER – áttekintő widget (gépgombok + Folyadék kártya)
//  Widget típus: Legfrissebb értékek (Latest values)
//  Datasource-ok: "Gép #1" … "Gép #5" entity aliasok
//  (kis konténernél csak "Gép #1" és "Gép #2")
// =====================================================================

// ------------------------- BEÁLLÍTÁSOK -------------------------------
const KONTENER = 'nagy';            // 'nagy' (3–5 gép) vagy 'kis' (1–2 gép)

const KEPEK = {                     // Képtár → kép → nyilvános (public) link
  nagyFekvo: '/api/images/public/H65qFzbj4Wb3VveoEwxTZXbq4lq6JCsP',   // nagy konténer, fekvő (2140×848)
  nagyAllo:  '/api/images/public/DyLYUDsOXg1EaWveXWBzJimMhLf0SLuv',   // nagy konténer, álló  (941×1672)
  kis:       '/api/images/public/KqsPYqRgW9UKojuc2RwelnTYjHUQKD4Y'    // kis konténer         (651×775)
};

const ALLAPOTOK = {                 // a gépnézet state-ek ID-ja (Állapotok kezelése → State ID)
  1: 'gep_1', 2: 'gep_2', 3: 'gep_3', 4: 'gep_4', 5: 'gep_5'
};

const URES_LINK = 'https://nextgennitrogen.hu';    // ha az aliasban nincs gép → "+" gomb ide visz
function gombFelirat(k, ds) { return 'Gép #' + k; } // felirat, ha van gép

// Ugyanúgy működik, mint a régi Folyadék widget:
//  - összes előállított = az összes datasource "total_l" kulcsának összege
//  - felhasznált = "used_l" szerver attribútum annál a datasource-nál, ahol szerepel
//    (a felhasználás asset), Hozzáadásnál oda mentődik
//  - negatív szám javít, a felhasznált nem mehet 0 alá
const FOLYADEK = {
  osszesKulcs:      'total_l',
  felhasznaltKulcs: 'used_l',
  felhasznaltScope: 'SERVER_SCOPE'
};

const ALLO_HATAR = 960;   // ez alatti képernyőszélességnél (tablet, mobil) álló kép

// Gombok helye a kép saját pixeleiben [x, y] (a gomb közepe).
// Ha a gépek sorrendje nem stimmel, csak cseréld fel a számokat (1–5).
const ELRENDEZES = {
  nagyFekvo: {
    w: 2140, h: 848, gomb: 88,
    gepek: { 3: [646, 109], 4: [1459, 105], 5: [1984, 435], 1: [594, 748], 2: [162, 443] },
    folyadek: { x: 850, y: 260, s: 1.3 }
  },
  nagyAllo: {
    w: 941, h: 1672, gomb: 96,
    gepek: { 3: [845, 523], 4: [845, 1172], 5: [450, 1555], 1: [85, 468], 2: [440, 110] },
    folyadek: { x: 128, y: 700, s: 1.75 }
  },
  kis: {
    w: 651, h: 775, gomb: 58,
    gepek: { 1: [95, 355], 2: [566, 345] },
    folyadek: { x: 190, y: 270, s: 0.83 }
  }
};
// ---------------------------------------------------------------------

let root = null;
const A = { valtozat: null, L: null, stage: null, gombok: {}, el: {}, felhasznalt: 0, osszes: 0, felhDs: null };

self.onInit = function () {
  const c = self.ctx.$container[0];
  c.innerHTML = '';
  root = el('div', 'nk-root');
  c.appendChild(root);
  self.onResize();
};

self.onResize = function () {
  if (!root) return;
  const W = self.ctx.width, H = self.ctx.height;
  if (!W || !H) return;
  const v = valtozat(W, H);
  if (v !== A.valtozat) { epit(v); self.onDataUpdated(); }
  const L = A.L;
  const s = Math.min(W / L.w, H / L.h);
  const x = (W - L.w * s) / 2, y = (H - L.h * s) / 2;
  A.stage.style.transform = 'translate(' + x + 'px,' + y + 'px) scale(' + s + ')';
};

self.onDataUpdated = function () {
  if (!A.stage) return;
  const g = gepLista();

  Object.keys(A.gombok).forEach(function (k) {
    const b = A.gombok[k], ds = g[k];
    b.textContent = ds ? gombFelirat(+k, ds) : '+';
    b.classList.toggle('nk-ures', !ds);
  });

  let ossz = 0;
  A.felhDs = null;
  (self.ctx.data || []).forEach(function (s) {
    if (!s.dataKey) return;
    const n = s.dataKey.name, l = s.dataKey.label;
    const v = utolso(s);
    if ((n === FOLYADEK.osszesKulcs || l === FOLYADEK.osszesKulcs) && num(v) !== null) ossz += num(v);
    if (n === FOLYADEK.felhasznaltKulcs || l === FOLYADEK.felhasznaltKulcs) {
      A.felhDs = s.datasource;
      if (num(v) !== null) A.felhasznalt = num(v);
    }
  });
  A.osszes = ossz;
  folyadekKiir();
};

function folyadekKiir() {
  const mar = A.osszes - A.felhasznalt;
  A.el.ossz.textContent = A.osszes.toFixed(1) + ' L';
  A.el.felh.textContent = A.felhasznalt.toFixed(1) + ' L';
  A.el.mar.textContent = mar.toFixed(1) + ' L';
  A.el.mar.style.color = mar < 0 ? '#b71c1c' : '';
}

self.onDestroy = function () { root = null; };

self.typeParameters = function () {
  return { maxDatasources: -1, maxDataKeys: -1, dataKeysOptional: true };
};

// ----------------------------- belső ---------------------------------

function valtozat(W, H) {
  if (KONTENER === 'kis') return 'kis';
  return (window.innerWidth < ALLO_HATAR || H > W) ? 'nagyAllo' : 'nagyFekvo';
}

function epit(v) {
  const L = ELRENDEZES[v];
  root.innerHTML = '';
  const stage = el('div', 'nk-stage');
  stage.style.width = L.w + 'px';
  stage.style.height = L.h + 'px';

  const bg = el('img', 'nk-bg');
  bg.src = KEPEK[v];
  bg.draggable = false;
  stage.appendChild(bg);

  A.gombok = {};
  Object.keys(L.gepek).forEach(function (k) {
    const p = L.gepek[k];
    const b = el('button', 'nk-gomb nk-ures');
    b.textContent = '+';
    b.style.left = p[0] + 'px';
    b.style.top = p[1] + 'px';
    b.style.minWidth = L.gomb + 'px';
    b.style.height = L.gomb + 'px';
    b.style.fontSize = Math.round(L.gomb * 0.22) + 'px';
    b.addEventListener('click', function () { kattint(+k); });
    stage.appendChild(b);
    A.gombok[k] = b;
  });

  const f = el('div', 'nk-folyadek');
  f.style.left = L.folyadek.x + 'px';
  f.style.top = L.folyadek.y + 'px';
  f.style.transform = 'scale(' + L.folyadek.s + ')';
  f.innerHTML =
    '<div class="nk-cim">Folyadék</div>' +
    '<div class="nk-sor"><span>Összes előállított</span><b data-id="ossz">0.0 L</b></div>' +
    '<div class="nk-sor"><span>Felhasznált</span><b data-id="felh">0.0 L</b></div>' +
    '<div class="nk-sor"><span>Maradék</span><b data-id="mar">0.0 L</b></div>' +
    '<div class="nk-bevitel"><input type="text" inputmode="decimal" placeholder="Felhasznált liter">' +
    '<button>Hozzáadás</button></div>' +
    '<div class="nk-msg" data-id="msg"></div>';
  stage.appendChild(f);

  A.el = {
    ossz: f.querySelector('[data-id=ossz]'),
    felh: f.querySelector('[data-id=felh]'),
    mar: f.querySelector('[data-id=mar]'),
    msg: f.querySelector('[data-id=msg]'),
    gomb: f.querySelector('button'),
    input: f.querySelector('input')
  };
  f.querySelector('button').addEventListener('click', hozzaad);
  A.el.input.addEventListener('keydown', function (e) { if (e.key === 'Enter') hozzaad(); });
  A.el.input.addEventListener('input', function () { A.el.input.classList.remove('nk-hiba'); });

  root.appendChild(stage);
  A.stage = stage;
  A.L = L;
  A.valtozat = v;
}

function kattint(k) {
  const ds = gepLista()[k];
  if (!ds) { window.open(URES_LINK, '_blank'); return; }
  self.ctx.stateController.openState(
    ALLAPOTOK[k],
    { entityId: { entityType: ds.entityType, id: ds.entityId }, entityName: ds.entityName },
    false
  );
}

function uzenet(szoveg, ok) {
  A.el.msg.textContent = szoveg;
  A.el.msg.style.color = ok ? '#1b5e20' : '#b71c1c';
}

function hozzaad() {
  const inp = A.el.input, gomb = A.el.gomb;
  const x = num(String(inp.value).trim().replace(',', '.'));
  if (x === null || x === 0) {
    inp.classList.add('nk-hiba');
    uzenet('Adj meg egy számot (a negatív szám javít).', false);
    return;
  }
  const ds = A.felhDs;
  if (!ds || !ds.entityId) { uzenet('Nincs "' + FOLYADEK.felhasznaltKulcs + '" adatforrás a widgetben.', false); return; }

  const uj = Math.max(0, Math.round((A.felhasznalt + x) * 100) / 100);
  gomb.disabled = true;
  self.ctx.attributeService.saveEntityAttributes(
    { entityType: ds.entityType, id: ds.entityId },
    FOLYADEK.felhasznaltScope,
    [{ key: FOLYADEK.felhasznaltKulcs, value: uj }]
  ).subscribe(
    function () {
      A.felhasznalt = uj;
      folyadekKiir();
      inp.value = '';
      uzenet('Mentve.', true);
      gomb.disabled = false;
    },
    function (e) {
      uzenet('Hiba: ' + ((e && e.error && e.error.message) || 'ismeretlen hiba'), false);
      gomb.disabled = false;
    }
  );
}

function gepLista() {
  const m = {};
  (self.ctx.datasources || []).forEach(function (ds) {
    const r = /#\s*(\d+)/.exec(ds.aliasName || '');
    if (r && ds.entityId) m[+r[1]] = ds;
  });
  return m;
}

function utolso(s) {
  return (s && s.data && s.data.length) ? s.data[s.data.length - 1][1] : null;
}

function num(v) {
  if (v === null || v === undefined || v === '') return null;
  const n = parseFloat(v);
  return isNaN(n) ? null : n;
}

function toast(msg, hiba) {
  try { hiba ? self.ctx.showErrorToast(msg) : self.ctx.showSuccessToast(msg); }
  catch (e) { console.log(msg); }
}

function el(tag, cls) {
  const e = document.createElement(tag);
  if (cls) e.className = cls;
  return e;
}

